// The administrator's Scoring settings page.
//
// Administrators change scoring through controls, never by typing a formula: a weight for every part of every drill, the
// benchmark values ("full marks at" / "zero points at"), a choice of scoring curve, penalty cost, pace strictness, the accuracy
// needed for full marks, and for the overall ranking the method, which attempt counts, and the facet weights.
//
// While editing, the page shows (1) a live preview of exactly what the Analysis page will say about the new formulas (generated by
// formulas.js), and (2) example attempts and example drivers scored with the CURRENT (saved) settings and with the NEW (draft)
// settings side by side. The examples can be edited, added, removed, and saved for other administrators. It also shows how the
// change would affect the attempts and drivers already recorded.
//
// Saving writes settings/scoring (read by everyone, so guests' on-the-spot scores use the same rules) and settings/scoringExamples.
// Every recorded attempt is then re-scored from its raw answers with the new settings (app.js -> applyScoring()).
import { esc, now } from "./util.js";
import { FACETS } from "./constants.js";
import {
	COMPONENTS,
	CURVES,
	DEFAULT_SCORING,
	FACET_ORDER,
	OVERALL_METHODS,
	ATTEMPT_RULES,
	normalizeScoring,
	validateScoring,
	scoreSubmission,
	driverSummary,
	settingsFor,
} from "./scoring.js";
import { facetCard, overallCard, bandsTableHtml, changesFromDefault, courseNameMap, FACET_NAMES, fmt } from "./formulas.js";
import { FACET_COURSE_GROUP } from "./constants.js";
import { publishedCourses, courseLabel } from "./courses.js";

import { territoryCard } from "./formulas.js";
import { offensePoints, defensePoints, pool as territoryPool, BONUS_CURVES, RANK_BASES, PENALTY_CURVES, penaltyBreakdown } from "./territorycore.js";

const clone = (value) => JSON.parse(JSON.stringify(value));
const two = (n) => (Number.isFinite(Number(n)) ? Number(n).toFixed(2) : "--");
const TABS = [["overall", "General statistics"], ["speed", FACET_NAMES.speed], ["territory", "Offense / Defense (Territory Breakthrough)"]];
const SHORT = { speed: "Speed", defense: "Defense", offense: "Offense" };

// ---------------------------------------------------------------- courses
// Each drill tab edits one set of settings at a time: the drill's DEFAULT settings ("" = attempts with no course recorded, and any
// course without its own settings) or one course's own settings. A course gets its own copy of the settings the first time one of
// its values is changed; until then it uses the default settings.
const currentCourse = (state) => state.scoringCourse?.[state.scoringTab] || "";
// Courses to offer for a drill: the published ones, plus any that still have saved settings (for example a deleted course).
function courseChoices(state, facet) {
	const courses = state.data.courses || {};
	const list = publishedCourses(courses, FACET_COURSE_GROUP[facet]);
	for (const key of Object.keys(state.scoringDraft.byCourse?.[facet] || {}))
		if (!list.some((c) => c.key === key)) list.push({ key, number: Number(key.split("-")[1]), name: courseLabel(courses, key) });
	for (const key of Object.keys(state.scoringDraft.byRobot?.[facet] || {}))
		if (!list.some((c) => c.key === key)) list.push({ key, number: Number(key.split("-")[1]), name: courseLabel(courses, key) });
	return list.sort((a, b) => a.number - b.number);
}
const profileOf = (state) => state.scoringProfile || "mecanum";
const robotOf = (state) => profileOf(state) === "swerve" ? "Swerve Chassis" : "REBUILT Robot";
const hasOwn = (draft, facet, key, profile = "mecanum") => Boolean(key && (profile === "swerve" ? draft.byRobot?.[facet]?.[key]?.swerve : draft.byCourse?.[facet]?.[key]));
const basePath = (facet, key, profile = "mecanum") => key ? (profile === "swerve" ? `byRobot.${facet}.${key}.swerve` : `byCourse.${facet}.${key}`) : `facets.${facet}`;
// Give a course its own copy of the settings (from the default) before its first change.
function materialize(draft, facet, key) {
	draft.byCourse ??= { speed: {}, defense: {}, offense: {} };
	draft.byCourse[facet] ??= {};
	if (key && !draft.byCourse[facet][key]) draft.byCourse[facet][key] = clone(draft.facets[facet]);
}

// ---------------------------------------------------------------- example data
// The raw answers each drill's score reads (the numeric questions on the built-in forms).
const exampleFields = (facet) => FACETS[facet].fields.filter((f) => f[2] === "number").map((f) => ({ key: f[0], label: f[6] || f[1] }));
export const DEFAULT_EXAMPLES = {
	facets: {
		speed: [
			{ label: "Fast and clean", totalTime: 16, lap1: 8, lap2: 8, penalties: 0 },
			{ label: "Fast, uneven laps", totalTime: 17, lap1: 6, lap2: 11, penalties: 1 },
			{ label: "Middle of the pack", totalTime: 22.5, lap1: 11, lap2: 11.5, penalties: 2 },
			{ label: "Slow but careful", totalTime: 29, lap1: 14, lap2: 15, penalties: 0 },
			{ label: "Fast, many penalties", totalTime: 18, lap1: 9, lap2: 9, penalties: 5 },
		],
		defense: [
			{ label: "Excellent defender", scorePreventions: 6, fuelPreventions: 4, secondsWasted: 30 },
			{ label: "Solid defender", scorePreventions: 3, fuelPreventions: 2, secondsWasted: 15 },
			{ label: "Rarely engaged", scorePreventions: 1, fuelPreventions: 0, secondsWasted: 5 },
			{ label: "Blocks scoring only", scorePreventions: 8, fuelPreventions: 1, secondsWasted: 20 },
			{ label: "Wastes time well", scorePreventions: 2, fuelPreventions: 5, secondsWasted: 40 },
		],
		offense: [
			{ label: "Benchmark run", fuelShot: 30, fuelScored: 20, evasions: 5 },
			{ label: "Accurate, few evasions", fuelShot: 20, fuelScored: 18, evasions: 2 },
			{ label: "High volume, inaccurate", fuelShot: 40, fuelScored: 10, evasions: 3 },
			{ label: "Great evader", fuelShot: 10, fuelScored: 8, evasions: 6 },
			{ label: "Shut down", fuelShot: 5, fuelScored: 1, evasions: 0 },
		],
	},
	// Example drivers for the overall ranking: facet scores out of 10, oldest attempt first, separated by commas (blank = not done).
	overall: [
		{ label: "Driver A (one perfect facet)", speed: "10", defense: "", offense: "" },
		{ label: "Driver B (well-rounded)", speed: "6", defense: "6", offense: "6" },
		{ label: "Improving driver", speed: "4, 7", defense: "5, 8", offense: "" },
		{ label: "Specialist", speed: "9.5", defense: "", offense: "9" },
		{ label: "Inconsistent driver", speed: "9, 3", defense: "8, 4", offense: "7, 2" },
	],
};
function normalizeExamples(saved) {
	const out = clone(DEFAULT_EXAMPLES);
	if (!saved || typeof saved !== "object") return out;
	for (const facet of FACET_ORDER) if (Array.isArray(saved.facets?.[facet])) out.facets[facet] = clone(saved.facets[facet]);
	if (Array.isArray(saved.overall)) out.overall = clone(saved.overall);
	return out;
}
// "4, 7" -> [4, 7] (each limited to 0-10); blank -> []
const parseScores = (text) =>
	String(text ?? "")
		.split(/[,;\s]+/)
		.map((x) => x.trim())
		.filter((x) => x !== "" && Number.isFinite(Number(x)))
		.map((x) => Math.max(0, Math.min(10, Number(x))));
// An example driver as the attempt list driverSummary() expects (createdAt increases left to right, so the last one is the most recent).
function exampleAttempts(row) {
	const subs = [];
	let n = 0;
	for (const facet of FACET_ORDER)
		parseScores(row[facet]).forEach((score) =>
			subs.push({ facet, createdAt: new Date(Date.UTC(2026, 0, 1, 0, 0, n++)).toISOString(), score: { final: score } }),
		);
	return subs;
}
// Standard competition ranking (1, 2, 2, 4) by score, highest first.
const ranks = (values) => values.map((v) => 1 + values.filter((x) => x > v).length);

// ---------------------------------------------------------------- state helpers
function ensureDraft(ctx) {
	const { state } = ctx;
	if (!state.scoringDraft) {
		state.scoringDraft = clone(state.scoring);
		state.scoringExamples = normalizeExamples(state.data.settings?.scoringExamples);
		state.scoringSavedExamples = clone(state.scoringExamples);
		state.scoringDirty = false;
	}
	state.scoringTab ??= "overall";
	return state.scoringDraft;
}
export function scoringIsDirty(state) {
	return Boolean(state.scoringDraft && state.scoringDirty);
}
export function resetScoringDraft(state) {
	state.scoringDraft = null;
	state.scoringDirty = false;
}
// The draft as a usable settings object, or null while it has problems (then the preview and "New" columns are not shown).
const usable = (draft) => (validateScoring(draft).length ? null : normalizeScoring(draft));
const getPath = (o, path) => path.split(".").reduce((x, k) => x?.[k], o);
function setPath(o, path, value) {
	const keys = path.split(".");
	const last = keys.pop();
	keys.reduce((x, k) => x[k], o)[last] = value;
}

// ---------------------------------------------------------------- rendering
const numberInput = (path, value, { min = 0, max = "", step = "any", label = "" } = {}) =>
	`<input type="number" data-sc="${path}" value="${esc(value)}" min="${min}" ${max !== "" ? `max="${max}"` : ""} step="${step}" inputmode="decimal" aria-label="${esc(label)}" />`;
function weightControl(path, value, label) {
	return `<div class="sc-weight"><span class="sc-weight-label">Weight</span><input type="range" min="0" max="100" step="1" data-sc="${path}" value="${esc(value)}" aria-label="${esc(label)} weight (slider)" />${numberInput(path, value, { min: 0, max: 100, step: "any", label: `${label} weight (percent)` })}<span class="sc-unit">%</span></div>`;
}
const totalHtml = (total) => {
	const ok = Math.abs(total - 100) < 0.001;
	return `<span class="sc-total ${ok ? "ok" : "bad"}">Total: ${fmt(total)}%${ok ? " ✓" : " (must be 100%)"}</span>`;
};
function componentEditor(facet, c, s, prefix) {
	const base = `${prefix}.${c.key}`;
	let body = "";
	if (c.kind === "range") {
		const time = c.unit === "s" && facet === "speed";
		body = `<p class="help">This component is mapped to a 0–10 score between the two benchmarks. Values beyond a benchmark are capped at 0 or 10. For time, lower values earn more; for the other measurements, higher values earn more.</p><div class="sc-grid"><label class="b-field"><span>Full marks (10) at</span>${numberInput(`${base}.full`, s.full, { label: `${c.label} full marks` })}<small class="help">${time ? "A drive at or faster than this excellent time earns 10 points for the time component." : `Reaching this ${esc(c.unitWord)} benchmark earns 10 points for this component.`}</small></label><label class="b-field"><span>Zero points at</span>${numberInput(`${base}.zero`, s.zero, { label: `${c.label} zero points` })}<small class="help">${time ? "A drive at or slower than this cutoff earns 0 time points." : "This measurement earns 0 points for this component; results below it are also capped at 0."}</small></label><label class="b-field sc-wide"><span>Scoring curve</span><select data-sc="${base}.curve">${Object.entries(CURVES)
			.map(([k, x]) => `<option value="${k}" ${s.curve === k ? "selected" : ""}>${esc(x.label)}</option>`)
			.join("")}</select><small class="help">The curve controls how scores rise between zero points and full marks. Straight line gives equal value to each step; diminishing returns rewards early progress more; accelerating places more points near the benchmark.</small></label></div>`;
	} else if (c.kind === "pace")
		body = `<div class="sc-grid"><label class="b-field sc-wide"><span>Strictness</span>${numberInput(`${base}.strictness`, s.strictness, { min: 0, max: 10, step: "0.1", label: "Pace strictness" })}<small class="help">This controls how strongly a difference between lap lengths lowers the pace score. 1 is the original rule (a lap twice as long as the other scores 5); 2 is twice as strict; 0 ignores lap consistency.</small></label></div>`;
	else if (c.kind === "penalty")
		body = `<div class="sc-grid"><label class="b-field sc-wide"><span>Points lost per penalty</span>${numberInput(`${base}.perPenalty`, s.perPenalty, { min: 0, max: 10, step: "0.5", label: `${c.label} points per penalty` })}<small class="help">The penalty component starts at 10. Subtract this amount once for each penalty; the result is capped at 0, then multiplied by this component's weight.</small></label></div>`;
	else
		body = `<div class="sc-grid"><label class="b-field sc-wide"><span>Accuracy for full marks (%)</span>${numberInput(`${base}.target`, s.target, { min: 1, max: 100, step: "any", label: "Accuracy for full marks" })}<small class="help">The scored-to-shot ratio is converted to a 0–10 value using this target. 100 means only perfect shooting earns 10; 80 means 80% accuracy or better earns 10. This component's weight determines its share of the final score.</small></label></div>`;
	return `<div class="sc-comp"><div class="sc-comp-head"><strong>${esc(c.label)}</strong><span class="sc-symbol">${esc(c.symbol)}</span></div>${weightControl(`${base}.weight`, s.weight, c.label)}${body}</div>`;
}
function courseBarHtml(state, facet) {
	const draft = state.scoringDraft,
		key = currentCourse(state),
		choices = courseChoices(state, facet), profile = profileOf(state);
	const pill = (k, label, own) =>
		`<button type="button" class="sc-course ${k === key ? "active" : ""}" data-sc-course="${esc(k)}" aria-pressed="${k === key}">${esc(label)}${own ? '<span class="sc-own">own settings</span>' : ""}</button>`;
	const copyFrom = [["", "Default settings"], ...choices.filter((c) => hasOwn(draft, facet, c.key, profile)).map((c) => [c.key, c.name])].filter(([k]) => k !== key);
	const note = !key
		? `These default settings score ${esc(FACET_NAMES[facet])} attempts with no course recorded${choices.some((c) => !hasOwn(draft, facet, c.key)) ? `, and these courses until they are given their own settings: ${esc(choices.filter((c) => !hasOwn(draft, facet, c.key)).map((c) => c.name).join(", "))}` : ""}.`
		: hasOwn(draft, facet, key, profile)
			? `${esc(courseLabel(state.data.courses, key))} has its own ${profile} settings. Changes here affect only this course and robot type.`
			: `${esc(courseLabel(state.data.courses, key))} currently uses the default settings. Change any value below to give this course its own settings.`;
	return `<div class="sc-courses"><div class="sc-courses-head"><strong>Course and robot</strong><span class="help">Set separate values for mecanum (REBUILT / REEFSCAPE) and Swerve.${choices.length ? "" : " No courses have been published for this drill yet (Course builder)."}</span></div><label class="b-field"><span>Robot drivetrain</span><select id="sc-profile"><option value="mecanum" ${profile === "mecanum" ? "selected" : ""}>Mecanum (REBUILT / REEFSCAPE)</option><option value="swerve" ${profile === "swerve" ? "selected" : ""}>Swerve Chassis</option></select></label><div class="sc-course-list" role="group" aria-label="Choose a course">${pill("", "Default settings", false)}${choices.map((c) => pill(c.key, `Course ${c.number}: ${c.name}`, hasOwn(draft, facet, c.key, profile))).join("")}</div><p class="sc-course-note">${note}</p>${
		key
			? `<div class="sc-course-tools">${copyFrom.length ? `<label class="sc-copy"><span>Copy values from</span><select id="sc-copy-from">${copyFrom.map(([k, label]) => `<option value="${esc(k)}">${esc(label)}</option>`).join("")}</select></label><button type="button" class="button button-secondary button-small" id="sc-copy">Copy</button>` : ""}${hasOwn(draft, facet, key, profile) ? `<button type="button" class="button button-secondary button-small" id="sc-use-default">Use the default settings for this robot and course</button>` : ""}</div>`
			: ""
	}</div>`;
}
// Territory Breakthrough (the Offensive / Defensive practice): plain numbers and a few choices, grouped by what they control. Every part
// of a round is a measured event, so there are no benchmarks or weights; these settings decide how many points each event is worth.
const TERRITORY_SECTIONS = [
	["Round", "The length of a round and the countdown before it.", [
		["duration", "Round length (seconds)", "How long each round lasts. A round also ends as soon as the Offensive Driver reaches the finish zone. The time bonus is measured against this length.", 1],
		["countdown", "Start countdown (seconds)", "The wait between both scorers being ready and the timers starting together on both laptops.", 0],
	]],
	["Checkpoint and finish points", "What each event is worth to the Offensive Driver. The Defensive Driver earns the same amount when the event is denied.", [
		["gate1Points", "Points for G1", "Offense earns this for crossing G1; defense earns it when G1 is not crossed.", 0],
		["gate2Points", "Points for G2", "Earned for crossing G2 (only after G1). Make later checkpoints worth more to reward getting deeper into the course.", 0],
		["gate3Points", "Points for G3", "Earned for crossing G3 (only after G2).", 0],
		["finishPoints", "Points for the finish", "Offense earns this for reaching the finish zone after G3; defense earns it when the finish is prevented.", 0],
	]],
	["Time bonus", "The extra points for a fast finish (offense) or a long delay (defense). The two always add up to the largest bonus.", [
		["timeBonus", "Largest time bonus", "Offense earns up to this much for finishing early. Defense earns the rest: all of it if the robot does not finish.", 0],
		["bonusCurve", "How the bonus shrinks", "", null, "select", BONUS_CURVES],
	]],
	["Penalties", "Penalties are always recorded. You can also make them cost points, and make repeated penalties cost more and more.", [
		["penaltyPoints", "Points lost for a regular penalty", "Taken off the score of the driver who received the penalty (never below 0). Leave at 0 for penalties to be recorded only. With a cost above 0, the two scores of a round no longer add up exactly to the total.", 0],
		["penaltyCurve", "How penalties add up", "", null, "select", PENALTY_CURVES],
		["penaltyBase", "Growth number (for the growing curve)", "With the growing curve, each penalty costs this many times the one before it: 2 means each costs double the last (1x, 2x, 4x, 8x...), 3 means triple (1x, 3x, 9x, 27x...). Ignored by the fixed curve.", 1],
		["pinningMultiplier", "Pinning penalty is worth (times a regular penalty)", "A pinning penalty costs this many times the value of a regular penalty at that point. 2 means twice as much.", 0],
		["pinSeconds", "Pinning time limit (seconds)", "How long the Defensive Driver may hold a pin before they must back off. Shown in the rules.", 1],
	]],
	["Rankings", "How the Offensive and Defensive leaderboards order drivers.", [
		["rankBasis", "Rank drivers by", "", null, "select", RANK_BASES],
		["recentRounds", "Number of recent rounds", "Used only when ranking by the most recent rounds.", 1],
	]],
	["Pairing suggestions", "Used only for the administrator's suggested pairings (they never change a score).", [
		["priorScore", "Assumed score for a new driver", "A role a driver has not played yet is assumed to score this, out of the points in a round.", 0],
		["priorWeight", "How many rounds the assumed score counts for", "Pairing suggestions blend the assumed score with a driver's real results, so one lucky or unlucky round cannot make someone look elite or hopeless. 0 uses only real results.", 0],
		["pairWeightOffense", "Weight of offensive skill", "How much a difference in OFFENSIVE skill counts toward two drivers not being well matched. Raise it above the defense weight to match mainly on offense.", 0],
		["pairWeightDefense", "Weight of defensive skill", "How much a difference in DEFENSIVE skill counts. Set one weight to 0 to ignore that role completely.", 0],
	]],
];
export const TERRITORY_TEXT_PATHS = ["territory.bonusCurve", "territory.rankBasis", "territory.penaltyCurve"];
function territorySettingsHtml(draft) {
	const t = draft.territory;
	const field = ([k, label, help, min, type, options]) => {
		const input = type === "select"
			? `<select data-sc="territory.${k}">${Object.entries(options).map(([id, o]) => `<option value="${id}" ${t[k] === id ? "selected" : ""}>${esc(o.label)}</option>`).join("")}</select><ul class="sc-option-notes">${Object.values(options).map((o) => `<li><strong>${esc(o.label.replace(" (recommended)", ""))}:</strong> ${esc(o.note)}</li>`).join("")}</ul>`
			: numberInput(`territory.${k}`, t[k], { min, label });
		return `<div class="sc-comp"><div class="sc-comp-head"><strong>${esc(label)}</strong></div>${help ? `<p class="help" style="margin:0 0 8px">${esc(help)}</p>` : ""}${input}</div>`;
	};
	return `<div class="panel-heading"><div><h3>Territory Breakthrough scoring</h3><p>The Offensive and Defensive drivers are scored from the checkpoints actually crossed and the time taken. With these settings a round is worth <strong>${two(territoryPool(t))}</strong> points in total.</p></div></div><div class="sc-body">${TERRITORY_SECTIONS.map(([title, note, fields]) => `<fieldset class="sc-group"><legend>${esc(title)}</legend><p class="help">${esc(note)}</p>${fields.map(field).join("")}</fieldset>`).join("")}${penaltyTableHtml(t)}<p class="help">Match rules are fixed: a match is three rounds of one run each, the drivers alternate roles every round, the driver with more points wins the round, and the first driver to win 2 of 3 rounds wins the match.</p></div>`;
}
// What 1 to 5 penalties cost with the current settings (regular, and the next one if it is a pinning penalty).
function penaltyTableHtml(t) {
	if (!t.penaltyPoints) return '<p class="help">Penalties currently cost no points (they are only recorded). Enter a cost above to see the table of what penalties would cost.</p>';
	const rows = [1, 2, 3, 4, 5].map((n) => {
		const reg = penaltyBreakdown({ penalties: n }, t),
			pin = penaltyBreakdown({ penalties: n - 1, pinningPenalties: 1 }, t);
		return `<tr><td>${n}</td><td>${two(reg.list[n - 1])}</td><td>${two(reg.cost)}</td><td>${two(pin.list[n - 1])}</td></tr>`;
	}).join("");
	return `<div class="table-wrap sc-table"><table><thead><tr><th>Penalty number</th><th>Cost of that regular penalty</th><th>Total after that many regular penalties</th><th>Cost if that one is a pinning penalty</th></tr></thead><tbody>${rows}</tbody></table></div>`;
}
function territoryExamplesHtml(state) {
	const saved = state.scoring.territory, next = usable(state.scoringDraft)?.territory;
	const cases = [["Finishes in 30 s", { g1: 5, g2: 10, g3: 20, finishTime: 30 }], ["Finishes in 40 s", { g1: 5, g2: 10, g3: 20, finishTime: 40 }], ["Finishes at the time limit", { g1: 5, g2: 10, g3: 20, finishTime: saved.duration }], ["Crosses 2 gates, no finish", { g1: 5, g2: 10 }], ["Crosses 1 gate, no finish", { g1: 5 }], ["Crosses no gates", {}]];
	const cell = (f, d, t) => (t ? two(f(d, t).points) : "--");
	return `<div class="table-wrap sc-table"><table><thead><tr><th>Example round</th><th>Offense now</th><th>Offense new</th><th>Defense now</th><th>Defense new</th></tr></thead><tbody>${cases.map(([n, d]) => `<tr><td>${esc(n)}</td><td>${cell(offensePoints, d, saved)}</td><td><strong>${cell(offensePoints, d, next)}</strong></td><td>${cell(defensePoints, d, saved)}</td><td><strong>${cell(defensePoints, d, next)}</strong></td></tr>`).join("")}</tbody></table></div>`;
}
function facetSettingsHtml(facet, state) {
	if (facet === "territory") return territorySettingsHtml(state.scoringDraft);
	const draft = state.scoringDraft,
		key = currentCourse(state),
		settings = settingsFor(draft, facet, key, robotOf(state)),
		prefix = basePath(facet, key, profileOf(state));
	const total = COMPONENTS[facet].reduce((t, c) => t + (Number(settings[c.key].weight) || 0), 0);
	const title = key ? `${FACET_NAMES[facet]} score: ${courseLabel(state.data.courses, key)}` : `${FACET_NAMES[facet]} score: default settings`;
	return `<div class="panel-heading"><div><h3>${esc(title)}</h3><p>Each part is scored out of 10; the weights decide how much each part counts in the final score.</p></div></div><div class="sc-body">${courseBarHtml(state, facet)}${COMPONENTS[facet]
		.map((c) => componentEditor(facet, c, settings[c.key], prefix))
		.join("")}<div class="sc-total-row" id="sc-total">${totalHtml(total)}<button type="button" class="button button-secondary button-small" data-sc-balance="${prefix}">Make weights add up to 100%</button><button type="button" class="button button-secondary button-small" data-sc-default="${facet}">Use original ${esc(SHORT[facet])} values</button></div></div>`;
}
function overallSettingsHtml(draft) {
	const o = draft.overall;
	const total = FACET_ORDER.reduce((t, k) => t + (Number(o.weights[k]) || 0), 0);
	return `<div class="panel-heading"><div><h3>Overall ranking (General statistics)</h3><p>How the facet scores become each driver's overall score on the leaderboard.</p></div></div><div class="sc-body">
  <fieldset class="sc-methods"><legend>Ranking method</legend>${Object.entries(OVERALL_METHODS)
		.map(
			([k, m]) =>
				`<label class="sc-method ${o.method === k ? "selected" : ""}"><input type="radio" name="sc-method" data-sc="overall.method" value="${k}" ${o.method === k ? "checked" : ""} /><span><strong>${esc(m.label)}</strong><small>${esc(m.help)}</small></span></label>`,
		)
		.join("")}</fieldset>
  <label class="b-field"><span>Which attempt counts in each facet</span><select data-sc="overall.attempt">${Object.entries(ATTEMPT_RULES)
		.map(([k, r]) => `<option value="${k}" ${o.attempt === k ? "selected" : ""}>${esc(r.label)}</option>`)
		.join("")}</select><small class="help">The original rule uses each driver's most recent attempt, so improvement shows straight away.</small></label>
  <div class="sc-comp"><div class="sc-comp-head"><strong>Facet weights</strong></div><p class="help" style="margin:0 0 10px">How much each facet counts in the facet average${o.method === "missingZero" ? " (here: in the weighted sum)" : ""}. An equal share each (33.34 / 33.33 / 33.33) treats all facets equally.</p>${FACET_ORDER.map(
		(k) => `<div class="sc-facet-weight"><span>${esc(FACET_NAMES[k])}</span>${weightControl(`overall.weights.${k}`, o.weights[k], FACET_NAMES[k])}</div>`,
	).join("")}</div>
  <div class="sc-total-row" id="sc-total">${totalHtml(total)}<button type="button" class="button button-secondary button-small" data-sc-balance="overall.weights">Make weights add up to 100%</button><button type="button" class="button button-secondary button-small" data-sc-default="overall">Use original overall settings</button></div>
</div>`;
}
function previewHtml(state) {
	const cfg = usable(state.scoringDraft);
	if (!cfg) return `<p class="notice">Fix the problems listed at the top of the page to see the preview.</p>`;
	const tab = state.scoringTab;
	const changes = changesFromDefault(cfg, courseNameMap(state.data.courses));
	const changed = changes.length
		? `<div class="eq-changes"><p><strong>Differences from the original DriveLab scoring</strong> (listed on the Analysis page):</p><ul>${changes.map((c) => `<li>${esc(c)}</li>`).join("")}</ul></div>`
		: `<p class="eq-note">These are the original DriveLab scoring settings.</p>`;
	if (tab === "territory") return `${changed}${territoryCard("offense", "Offensive driving", cfg)}${territoryCard("defense", "Defensive driving", cfg)}`;
	const key = currentCourse(state);
	const subtitle = key ? (hasOwn(state.scoringDraft, tab, key, profileOf(state)) ? `${courseLabel(state.data.courses, key)} (its own settings)` : `${courseLabel(state.data.courses, key)} (uses the default settings)`) : "Default settings";
	return `${changed}${tab === "overall" ? `${overallCard(cfg)}<h4 class="sc-sub">Possible overall score by facets completed</h4>${bandsTableHtml(cfg)}` : facetCard(tab, FACET_NAMES[tab], cfg, key, `${subtitle} · ${profileOf(state) === "swerve" ? "Swerve" : "Mecanum"}`, robotOf(state))}`;
}

// Example attempts for one drill: raw answers (editable), each part's new score, and the final score now vs. with the draft.
function facetExamplesHtml(state, facet) {
	const fields = exampleFields(facet);
	const rows = state.scoringExamples.facets[facet];
	const comps = COMPONENTS[facet];
	return `<div class="table-wrap sc-table"><table><thead><tr><th>Example</th>${fields.map((f) => `<th class="sc-in">${esc(f.label)}</th>`).join("")}${comps.map((c) => `<th class="sc-part" title="${esc(c.label)} (new settings)">${esc(c.symbol)}</th>`).join("")}<th>Current score</th><th>New score</th><th>Change</th><th class="no-print"><span class="sr-only">Remove</span></th></tr></thead><tbody>${
		rows
			.map(
				(r, i) =>
					`<tr><td><input class="sc-label-input" data-ex="facets.${facet}.${i}.label" value="${esc(r.label)}" aria-label="Example name" /></td>${fields
						.map((f) => `<td class="sc-in"><input type="number" min="0" step="any" inputmode="decimal" data-ex="facets.${facet}.${i}.${f.key}" value="${esc(r[f.key] ?? "")}" aria-label="${esc(f.label)}" /></td>`)
						.join("")}${comps.map((c) => `<td class="sc-part-val" data-r="${i}-${c.key}"></td>`).join("")}<td data-r="${i}-before"></td><td class="sc-new" data-r="${i}-after"></td><td data-r="${i}-delta"></td><td class="no-print"><button type="button" class="icon-btn danger" data-ex-remove="${i}" title="Remove this example" aria-label="Remove this example">×</button></td></tr>`,
			)
			.join("") || `<tr><td colspan="${fields.length + comps.length + 5}" class="empty">No examples. Press Add example.</td></tr>`
	}</tbody></table></div><p class="help sc-legend">${comps.map((c) => `<strong>${esc(c.symbol)}</strong> = ${esc(c.label)}`).join(" · ")} (each part out of 10, with the new settings).</p>`;
}
function overallExamplesHtml(state) {
	const rows = state.scoringExamples.overall;
	return `<div class="table-wrap sc-table"><table><thead><tr><th>Example driver</th>${FACET_ORDER.map((k) => `<th class="sc-in">${SHORT[k]}</th>`).join("")}<th>Facets</th><th>Current overall</th><th>Current rank</th><th>New overall</th><th>New rank</th><th>Change</th><th class="no-print"><span class="sr-only">Remove</span></th></tr></thead><tbody>${
		rows
			.map(
				(r, i) =>
					`<tr><td><input class="sc-label-input" data-ex="overall.${i}.label" value="${esc(r.label)}" aria-label="Example driver name" /></td>${FACET_ORDER.map(
						(k) => `<td class="sc-in"><input data-ex="overall.${i}.${k}" value="${esc(r[k] ?? "")}" placeholder="--" inputmode="decimal" aria-label="${SHORT[k]} scores" /></td>`,
					).join("")}${["facets", "before", "brank"].map((k) => `<td data-r="${i}-${k}"></td>`).join("")}<td class="sc-new" data-r="${i}-after"></td><td data-r="${i}-arank"></td><td data-r="${i}-delta"></td><td class="no-print"><button type="button" class="icon-btn danger" data-ex-remove="${i}" title="Remove this example" aria-label="Remove this example">×</button></td></tr>`,
			)
			.join("") || `<tr><td colspan="12" class="empty">No examples. Press Add example.</td></tr>`
	}</tbody></table></div><p class="help sc-legend">Enter each facet's scores out of 10, oldest first, separated by commas (for example <code>4, 7</code>). Leave a box blank if the driver has not done that facet. Ranks compare the example drivers with each other.</p>`;
}
const changeCell = (before, after) => {
	if (!Number.isFinite(after) || !Number.isFinite(before)) return `<span class="sc-delta">--</span>`;
	const d = Math.round((after - before) * 100) / 100;
	return `<span class="sc-delta ${d > 0 ? "up" : d < 0 ? "down" : ""}">${d > 0 ? "+" : ""}${d.toFixed(2)}</span>`;
};
const rankCell = (before, after) => {
	if (!after) return "--";
	const d = before - after;
	return `#${after}${d ? ` <small class="sc-delta ${d > 0 ? "up" : "down"}">${d > 0 ? "▲" : "▼"}${Math.abs(d)}</small>` : ""}`;
};
// Fills in every result cell of the example table (inputs are left untouched, so typing never loses focus).
function refreshExampleResults(state) {
	const tab = state.scoringTab,
		saved = state.scoring,
		next = usable(state.scoringDraft);
	const put = (key, html) => {
		const cell = document.querySelector(`[data-r="${key}"]`);
		if (cell) cell.innerHTML = html;
	};
	if (tab === "overall") {
		const rows = state.scoringExamples.overall;
		const before = rows.map((r) => driverSummary(exampleAttempts(r), saved));
		const after = rows.map((r) => (next ? driverSummary(exampleAttempts(r), next) : null));
		const rb = ranks(before.map((x) => (x.completed ? x.overall : -1)));
		const ra = next ? ranks(after.map((x) => (x.completed ? x.overall : -1))) : [];
		rows.forEach((_, i) => {
			const b = before[i],
				a = after[i];
			put(`${i}-facets`, `${b.completed}/${FACET_ORDER.length}`);
			put(`${i}-before`, b.completed ? two(b.overall) : "--");
			put(`${i}-brank`, b.completed ? `#${rb[i]}` : "--");
			put(`${i}-after`, a && a.completed ? `<strong>${two(a.overall)}</strong>` : "--");
			put(`${i}-arank`, a && a.completed ? rankCell(rb[i], ra[i]) : "--");
			put(`${i}-delta`, a && b.completed ? changeCell(b.overall, a.overall) : "--");
		});
		return;
	}
	state.scoringExamples.facets[tab].forEach((r, i) => {
		const sub = { facet: tab, data: { ...r, course: currentCourse(state), robot: robotOf(state) } }; // scored with the selected course and robot settings
		const b = scoreSubmission(sub, saved);
		const a = next ? scoreSubmission(sub, next) : null;
		COMPONENTS[tab].forEach((c) => put(`${i}-${c.key}`, a ? two(a[c.key]) : "--"));
		put(`${i}-before`, two(b.final));
		put(`${i}-after`, a ? `<strong>${two(a.final)}</strong>` : "--");
		put(`${i}-delta`, a ? changeCell(b.final, a.final) : "--");
	});
}
// How the change would affect what is already recorded.
function impactHtml(state) {
	const next = usable(state.scoringDraft);
	const built = state.data.submissions.filter((x) => FACET_ORDER.includes(x.facet) && (x.facet === "speed" || x.data?.mode === "territory"));
	if (!built.length) return `<p class="help">No attempts have been recorded yet, so only the examples above are affected.</p>`;
	if (!next) return `<p class="help">Fix the problems listed at the top of the page to see the effect on recorded attempts.</p>`;
	const rescore = (cfg) => built.map((x) => ({ ...x, score: scoreSubmission(x, cfg) }));
	const before = rescore(state.scoring),
		after = rescore(next);
	if (state.scoringTab !== "overall") {
		const f = state.scoringTab;
		if (f === "territory") {
			const b = before.filter((x) => x.facet !== "speed"),
				a = after.filter((x) => x.facet !== "speed");
			if (!b.length) return `<p class="help">No Territory Breakthrough rounds have been recorded yet.</p>`;
			const moved = b.filter((x, i) => Math.abs(x.score.final - a[i].score.final) >= 0.005).length;
			return `<p class="sc-impact">${b.length} recorded Offensive / Defensive form${b.length === 1 ? "" : "s"}; ${moved} would change score. Saving re-scores them from their recorded checkpoint times.</p>`;
		}
		const b = before.filter((x) => x.facet === f),
			a = after.filter((x) => x.facet === f);
		if (!b.length) return `<p class="help">No ${esc(FACET_NAMES[f])} attempts have been recorded yet.</p>`;
		const avg = (l) => l.reduce((t, x) => t + x.score.final, 0) / l.length;
		const moved = b.filter((x, i) => Math.abs(x.score.final - a[i].score.final) >= 0.005).length;
		return `<p class="sc-impact">Across the <strong>${b.length}</strong> recorded ${esc(FACET_NAMES[f])} attempt${b.length === 1 ? "" : "s"}, the average score would go from <strong>${two(avg(b))}</strong> to <strong>${two(avg(a))}</strong>; ${moved} attempt${moved === 1 ? "" : "s"} would change.</p>`;
	}
	const board = (subs, cfg) => {
		const by = {};
		subs.forEach((x) => (by[x.driverName] ??= []).push(x));
		const rows = Object.entries(by).map(([name, list]) => ({ name, ...driverSummary(list, cfg) }));
		const r = ranks(rows.map((x) => x.overall));
		return Object.fromEntries(rows.map((x, i) => [x.name, { ...x, rank: r[i] }]));
	};
	const b = board(before, state.scoring),
		a = board(after, next);
	const names = Object.keys(a).sort((x, y) => a[x].rank - a[y].rank || x.localeCompare(y));
	const moved = names.filter((n) => a[n].rank !== b[n].rank).length;
	return `<p class="sc-impact">${names.length} recorded driver${names.length === 1 ? "" : "s"}; ${moved} would change rank.</p><div class="table-wrap sc-table" style="max-height:360px"><table><thead><tr><th>Driver</th><th>Facets</th><th>Current overall</th><th>Current rank</th><th>New overall</th><th>New rank</th><th>Change</th></tr></thead><tbody>${names
		.map(
			(n) =>
				`<tr><td><strong>${esc(n)}</strong></td><td>${a[n].completed}/${FACET_ORDER.length}</td><td>${two(b[n].overall)}</td><td>#${b[n].rank}</td><td><strong>${two(a[n].overall)}</strong></td><td>${rankCell(b[n].rank, a[n].rank)}</td><td>${changeCell(b[n].overall, a[n].overall)}</td></tr>`,
		)
		.join("")}</tbody></table></div>`;
}

export function renderScoringEditor(ctx) {
	const { state } = ctx;
	const draft = ensureDraft(ctx);
	const tab = state.scoringTab;
	const actions = `<div class="hero-actions sc-actions"><span id="sc-dirty" class="sc-dirty" ${state.scoringDirty ? "" : "hidden"}>Unsaved changes</span><button class="button button-secondary" id="sc-restore" type="button">Restore all original scoring</button><button class="button button-secondary" id="sc-discard" type="button">Discard changes</button><button class="button" id="sc-save" type="button">Save scoring settings</button></div>`;
	return `${ctx.pageHeader("Scoring settings", "Choose how each drill and the overall ranking are scored. Saving re-scores every recorded attempt from its raw answers, and the Analysis page explains the new formulas automatically.", actions)}
<div id="sc-errors"></div>
<div class="sc-tabs" role="tablist">${TABS.map(([k, label]) => `<button type="button" role="tab" class="sc-tab ${tab === k ? "active" : ""}" aria-selected="${tab === k}" data-sc-tab="${k}">${esc(label)}</button>`).join("")}</div>
<div class="sc-layout">
  <section class="panel sc-settings" id="sc-settings">${tab === "overall" ? overallSettingsHtml(draft) : facetSettingsHtml(tab, state)}</section>
  <section class="panel sc-preview"><div class="panel-heading"><div><h3>Live preview of the Analysis page</h3><p>Generated automatically from the settings on the left. This is the explanation administrators will see on the Analysis page after saving.</p></div></div><div class="eq-body" id="sc-preview">${previewHtml(state)}</div></section>
</div>
<section class="panel sc-examples"><div class="panel-heading"><div><h3>${tab === "overall" ? "Example drivers" : `Example ${esc(tab === "territory" ? "Territory Breakthrough" : FACET_NAMES[tab])} ${tab === "territory" ? "rounds" : "attempts"}${tab === "territory" ? "" : currentCourse(state) ? ` on ${esc(courseLabel(state.data.courses, currentCourse(state)))}` : " (default settings)"}`}</h3><p><strong>Current</strong> uses the saved settings; <strong>New</strong> uses the settings on this page${tab === "overall" ? "" : " for the course selected above"}. Edit any example, or add your own, to see how the change affects scores.</p></div>${tab === "territory" ? "" : '<div class="item-actions"><button type="button" class="button button-secondary button-small" id="ex-add">Add example</button><button type="button" class="button button-secondary button-small" id="ex-reset">Reset examples</button></div>'}</div><div class="sc-examples-body" id="sc-tex">${tab === "overall" ? overallExamplesHtml(state) : tab === "territory" ? territoryExamplesHtml(state) : facetExamplesHtml(state, tab)}</div></section>
<section class="panel sc-examples"><div class="panel-heading"><div><h3>Effect on recorded ${tab === "overall" ? "drivers" : "attempts"}</h3><p>${tab === "overall" ? "The real leaderboard re-scored with the settings on this page (all drills and the overall ranking)." : "The real attempts for this drill, re-scored with the settings on this page."}</p></div></div><div class="sc-examples-body" id="sc-impact">${impactHtml(state)}</div></section>`;
}

export function bindScoringEditor(ctx) {
	const { state, store, toast } = ctx;
	ensureDraft(ctx);
	const dirtyBadge = document.querySelector("#sc-dirty");
	const markDirty = () => {
		state.scoringDirty = true;
		dirtyBadge.hidden = false;
	};
	const showErrors = () => {
		const problems = validateScoring(state.scoringDraft);
		document.querySelector("#sc-errors").innerHTML = problems.length
			? `<div class="notice error"><strong>Fix these before saving:</strong><ul>${problems.map((p) => `<li>${esc(p)}</li>`).join("")}</ul></div>`
			: "";
		return problems;
	};
	// Everything that depends on the draft, redrawn without touching the inputs being typed in.
	const refresh = () => {
		showErrors();
		const total =
			state.scoringTab === "territory" ? 0 : state.scoringTab === "overall"
				? FACET_ORDER.reduce((t, k) => t + (Number(state.scoringDraft.overall.weights[k]) || 0), 0)
				: COMPONENTS[state.scoringTab].reduce((t, c) => t + (Number(settingsFor(state.scoringDraft, state.scoringTab, currentCourse(state), robotOf(state))[c.key].weight) || 0), 0);
		const totalBox = document.querySelector("#sc-total .sc-total");
		if (totalBox) totalBox.outerHTML = totalHtml(total);
		document.querySelector("#sc-preview").innerHTML = previewHtml(state);
		document.querySelector("#sc-impact").innerHTML = impactHtml(state);
		if (state.scoringTab === "territory") document.querySelector("#sc-tex").innerHTML = territoryExamplesHtml(state);
		else refreshExampleResults(state);
	};
	const redraw = () => {
		const y = window.scrollY;
		ctx.render();
		window.scrollTo(0, y);
	};

	// Settings inputs: write straight into the draft. The slider and the number box for the same weight mirror each other.
	const settings = document.querySelector("#sc-settings");
	const onSetting = (e) => {
		const el = e.target.closest("[data-sc]");
		if (!el) return;
		const path = el.dataset.sc;
		const parts = path.split(".");
		if (parts[0] === "byCourse") {
			const first = !hasOwn(state.scoringDraft, parts[1], parts[2]);
			materialize(state.scoringDraft, parts[1], parts[2]); // the course's first change gives it its own settings
			if (first) setTimeout(refreshCourseBar); // show the "own settings" badge and tools without losing focus
		}
		if (parts[0] === "byRobot") {
			state.scoringDraft.byRobot ??= { speed: {}, defense: {}, offense: {} };
			state.scoringDraft.byRobot[parts[1]] ??= {};
			state.scoringDraft.byRobot[parts[1]][parts[2]] ??= {};
			state.scoringDraft.byRobot[parts[1]][parts[2]].swerve ??= clone(state.scoringDraft.byCourse?.[parts[1]]?.[parts[2]] || state.scoringDraft.facets[parts[1]]);
		}
		const textual = path.endsWith(".curve") || path === "overall.method" || path === "overall.attempt" || TERRITORY_TEXT_PATHS.includes(path);
		const value = textual ? el.value : el.value === "" ? "" : Number(el.value);
		setPath(state.scoringDraft, path, value);
		settings.querySelectorAll(`[data-sc="${path}"]`).forEach((other) => {
			if (other !== el && other.type !== "radio") other.value = el.value;
		});
		if (path === "overall.method") settings.querySelectorAll(".sc-method").forEach((m) => m.classList.toggle("selected", m.querySelector("input").checked));
		markDirty();
		refresh();
	};
	settings.addEventListener("input", onSetting);
	settings.addEventListener("change", onSetting);
	// "Make weights add up to 100%": scale the current weights proportionally (equal split if they are all 0).
	settings.querySelectorAll("[data-sc-balance]").forEach(
		(b) =>
			(b.onclick = () => {
				const path = b.dataset.scBalance;
				const bits = path.split(".");
				if (bits[0] === "byCourse") materialize(state.scoringDraft, bits[1], bits[2]);
				if (bits[0] === "byRobot") {
					state.scoringDraft.byRobot ??= { speed: {}, defense: {}, offense: {} };
					state.scoringDraft.byRobot[bits[1]] ??= {};
					state.scoringDraft.byRobot[bits[1]][bits[2]] ??= {};
					state.scoringDraft.byRobot[bits[1]][bits[2]].swerve ??= clone(state.scoringDraft.byCourse?.[bits[1]]?.[bits[2]] || state.scoringDraft.facets[bits[1]]);
				}
				const group = getPath(state.scoringDraft, path);
				const flat = path === "overall.weights"; // { speed: 25, ... } rather than { time: { weight: 70 }, ... }
				const keys = Object.keys(group);
				const read = (k) => Number(flat ? group[k] : group[k].weight) || 0;
				const write = (k, value) => (flat ? (group[k] = value) : (group[k].weight = value));
				const total = keys.reduce((t, k) => t + read(k), 0);
				const values = keys.map((k) => Math.round((total > 0 ? (read(k) * 100) / total : 100 / keys.length) * 100) / 100); // 2 decimals: 33.33 / 33.33 / 33.34
				// Rounding can leave the total at 99.9 or 100.1; the largest weight absorbs the difference.
				const biggest = values.indexOf(Math.max(...values));
				values[biggest] = Math.round((values[biggest] + 100 - values.reduce((a, x) => a + x, 0)) * 100) / 100;
				keys.forEach((k, i) => write(k, values[i]));
				markDirty();
				redraw();
			}),
	);
	settings.querySelectorAll("[data-sc-default]").forEach(
		(b) =>
			(b.onclick = () => {
				const k = b.dataset.scDefault;
				const course = currentCourse(state);
				if (k === "overall") state.scoringDraft.overall = clone(DEFAULT_SCORING.overall);
				else if (course && profileOf(state) === "swerve") {
					state.scoringDraft.byRobot ??= { speed: {}, defense: {}, offense: {} };
					state.scoringDraft.byRobot[k] ??= {};
					state.scoringDraft.byRobot[k][course] ??= {};
					state.scoringDraft.byRobot[k][course].swerve = clone(DEFAULT_SCORING.facets[k]);
				}
				else if (course) {
					materialize(state.scoringDraft, k, course);
					state.scoringDraft.byCourse[k][course] = clone(DEFAULT_SCORING.facets[k]);
				} else state.scoringDraft.facets[k] = clone(DEFAULT_SCORING.facets[k]);
				markDirty();
				redraw();
			}),
	);

	// Course picker and its tools (drill tabs only). refreshCourseBar() redraws only this bar, so typing is never interrupted.
	const bindCourseBar = (root) => {
		root.querySelector("#sc-profile")?.addEventListener("change", e => { state.scoringProfile = e.target.value; redraw(); });
		root.querySelectorAll("[data-sc-course]").forEach(
			(b) =>
				(b.onclick = () => {
					state.scoringCourse = { ...(state.scoringCourse || {}), [state.scoringTab]: b.dataset.scCourse };
					redraw();
				}),
		);
		root.querySelector("#sc-copy")?.addEventListener("click", () => {
			const facet = state.scoringTab,
				key = currentCourse(state),
				from = document.querySelector("#sc-copy-from").value;
			materialize(state.scoringDraft, facet, key);
				if (profileOf(state) === "swerve") {
					state.scoringDraft.byRobot ??= { speed: {}, defense: {}, offense: {} };
					state.scoringDraft.byRobot[facet] ??= {};
					state.scoringDraft.byRobot[facet][key] ??= {};
					state.scoringDraft.byRobot[facet][key].swerve = clone(settingsFor(state.scoringDraft, facet, from, robotOf(state)));
				} else state.scoringDraft.byCourse[facet][key] = clone(settingsFor(state.scoringDraft, facet, from, robotOf(state)));
			markDirty();
			redraw();
		});
		root.querySelector("#sc-use-default")?.addEventListener("click", () => {
			const facet = state.scoringTab,
				key = currentCourse(state);
			if (!confirm("Remove this course's own settings? Its attempts will be scored with the default settings (after you save).")) return;
			if (profileOf(state) === "swerve") delete state.scoringDraft.byRobot?.[facet]?.[key]?.swerve;
			else delete state.scoringDraft.byCourse[facet][key];
			markDirty();
			redraw();
		});
	};
	const refreshCourseBar = () => {
		const bar = document.querySelector(".sc-courses");
		if (!bar || state.scoringTab === "overall") return;
		bar.outerHTML = courseBarHtml(state, state.scoringTab);
		bindCourseBar(document.querySelector(".sc-courses"));
	};
	const courseBar = document.querySelector(".sc-courses");
	if (courseBar) bindCourseBar(courseBar);
	document.querySelectorAll("[data-sc-tab]").forEach(
		(b) =>
			(b.onclick = () => {
				state.scoringTab = b.dataset.scTab;
				redraw();
			}),
	);

	// Examples: editing changes only the result cells; adding / removing redraws the page.
	const examples = state.scoringExamples;
	document.querySelectorAll("[data-ex]").forEach((input) =>
		input.addEventListener("input", () => {
			const path = input.dataset.ex;
			const numeric = input.type === "number";
			setPath(examples, path, numeric ? (input.value === "" ? "" : Number(input.value)) : input.value);
			markDirty();
			refreshExampleResults(state);
		}),
	);
	document.querySelectorAll("[data-ex-remove]").forEach(
		(b) =>
			(b.onclick = () => {
				const list = state.scoringTab === "overall" ? examples.overall : examples.facets[state.scoringTab];
				list.splice(Number(b.dataset.exRemove), 1);
				markDirty();
				redraw();
			}),
	);
	(document.querySelector("#ex-add") || {}).onclick = () => {
		if (state.scoringTab === "overall")
			examples.overall.push({ label: `Example driver ${examples.overall.length + 1}`, speed: "", defense: "", offense: "" });
		else {
			const row = { label: `Example ${examples.facets[state.scoringTab].length + 1}` };
			exampleFields(state.scoringTab).forEach((f) => (row[f.key] = 0));
			examples.facets[state.scoringTab].push(row);
		}
		markDirty();
		redraw();
		const inputs = document.querySelectorAll(".sc-label-input");
		inputs[inputs.length - 1]?.select();
	};
	(document.querySelector("#ex-reset") || {}).onclick = () => {
		if (state.scoringTab === "overall") examples.overall = clone(DEFAULT_EXAMPLES.overall);
		else examples.facets[state.scoringTab] = clone(DEFAULT_EXAMPLES.facets[state.scoringTab]);
		markDirty();
		redraw();
	};

	// Page actions.
	document.querySelector("#sc-restore").onclick = () => {
		if (!confirm("Put every drill and the overall ranking back to the original DriveLab scoring? Nothing is saved until you press Save scoring settings.")) return;
		state.scoringDraft = clone(DEFAULT_SCORING);
		markDirty();
		redraw();
	};
	document.querySelector("#sc-discard").onclick = () => {
		if (state.scoringDirty && !confirm("Discard all unsaved changes on this page?")) return;
		state.scoringDraft = clone(state.scoring);
		state.scoringExamples = clone(state.scoringSavedExamples);
		state.scoringDirty = false;
		redraw();
	};
	document.querySelector("#sc-save").onclick = async (e) => {
		if (showErrors().length) {
			window.scrollTo({ top: 0, behavior: "smooth" });
			toast("Fix the problems listed at the top before saving.");
			return;
		}
		const button = e.currentTarget;
		button.disabled = true;
		const cfg = { ...normalizeScoring(state.scoringDraft), updatedAt: now() };
		try {
			await store.saveSetting("scoring", cfg);
			await store.saveSetting("scoringExamples", examples);
		} catch (err) {
			button.disabled = false;
			toast(`Could not save the scoring settings: ${err.message}`);
			return;
		}
		state.data.settings = { ...(state.data.settings || {}), scoring: cfg, scoringExamples: clone(examples) };
		ctx.applyScoring(cfg);
		state.scoringDraft = clone(state.scoring);
		state.scoringSavedExamples = clone(examples);
		state.scoringDirty = false;
		redraw();
		toast("Scoring settings saved. Every recorded attempt has been re-scored.");
	};

	refresh();
}
